const express = require('express');
const griddb = require('griddb-node-api');
const db = require('../db');

const app = express();
app.use(express.json());

let gridStore;
griddb.StoreFactory.getInstance().getStore({
  host: process.env.GRIDDB_HOST,
  port: parseInt(process.env.GRIDDB_PORT || '10001'),
  clusterName: process.env.GRIDDB_CLUSTER,
  username: process.env.GRIDDB_USER,
  password: process.env.GRIDDB_PASSWORD
}).then(store => { gridStore = store; });

app.put('/api/sensors/:sensorTag/alert-threshold', async (req, res) => {
  const { sensorTag } = req.params;
  const { maxCriticalLimit, warningLimit } = req.body;

  // Verify that the sensor tag belongs to the authenticated user's tenant/facility
  const sensor = await db('facility_sensors')
    .where({ tag: sensorTag, tenant_id: req.user.tenantId })
    .first();
  if (!sensor) {
    return res.status(404).json({ error: 'Sensor configuration not found' });
  }

  try {
    const container = await gridStore.getContainer('sensor_config_collection');
    const query = container.query(`SELECT * WHERE tag = '${sensorTag}'`);
    const rowSet = await query.fetch(true);

    if (!rowSet.hasNext()) {
      return res.status(404).json({ error: 'Sensor configuration not found in GridDB' });
    }

    const row = rowSet.next();
    row[2] = warningLimit;
    row[3] = maxCriticalLimit;
    await rowSet.update(row);

    return res.json({ status: 'Threshold updated', sensorTag, warningLimit, maxCriticalLimit });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to update alert limits in GridDB' });
  }
});

module.exports = app;
